"""Update the Team Workbook for Tier 4 and Part 2: tier, FR36/FR37/NFR7, RTM design elements, Tier Checklist, Feedback Log.
Usage: python update_workbook.py <in.xlsx> <out.xlsx>"""
import copy
import sys
import openpyxl

src, dst = sys.argv[1], sys.argv[2]
wb = openpyxl.load_workbook(src)

# ---- Team & Tier
t = wb["Team & Tier"]
t["B5"] = "Tier 4"
t["B7"] = "Tier 4 – approved verbally at Presentation 1 (written confirmation requested)"
for c in ("E18", "E19"):
    t[c] = "Designed (Part 2)"

# ---- Requirements: FR36, FR37, NFR7 in the empty rows 46–48 (IDs are generated by the sheet's formula)
r = wb["Requirements"]
new = [
    (46, "FR", "The system shall process PayPal payments of Foreign Tourists through the live PayPal Developer sandbox (Orders v2: create, buyer approval, capture), store the PayPal order and capture IDs on the payment record, and refund a cancelled paid order through the sandbox.", "Must", "UC1", "BR13, BR16", "None", "524H0055", "Tier 4 (a) · sandbox order captured and refunded in a test run"),
    (47, "FR", "The system shall give System Admins an interactive dashboard with today's orders, revenue, average preparation time and Quiet Kitchen share, live hub load, orders by state and payment mix, date-range and hub filters, and the heavy-rain switch.", "Must", "UC2 + System settings (ADM)", "BR5, BR7, BR8", "R1, R2", "524H0169", "Tier 4 (b) · values match R1/R2 for the same filter"),
    (48, "NFR", "Testability (Tier 4): automated Playwright end-to-end tests shall cover a Local order with COD, a Tourist order paid in the PayPal sandbox, kitchen and shipper transitions, one rejected invalid transition, and reports R1 and R2; they run headless with one command and pass 100% on the release build.", "Must", "Shared", "BR13–BR15", "R1, R2", "524H0055, 524H0169", "dotnet test --filter Category=E2E · HTML report and traces kept"),
]
style_row = 45
for row, typ, text, prio, uc, br, rep, owner, note in new:
    vals = {"B": text, "C": typ, "D": prio, "E": uc, "F": br, "G": rep, "H": owner, "I": note, "K": "Approved (Tier 4)"}
    for col, v in vals.items():
        cell = r[f"{col}{row}"]
        cell.value = v
        ref = r[f"{col}{style_row}"]
        cell.font, cell.alignment, cell.border, cell.fill = copy.copy(ref.font), copy.copy(ref.alignment), copy.copy(ref.border), copy.copy(ref.fill)

# ---- RTM: design element for every requirement (row r in RTM mirrors row r in Requirements)
DESIGN = [
    "Class diagram 2.8 (User → Customer → Local/Tourist); ERD 2.12 (TPT profiles)",
    "User.PasswordHash (Identity PBKDF2); ERD 2.12 Users.Email UK",
    "LocalCustomer + LocalCustomerProfiles; Register screen 2.24",
    "ForeignTourist + TouristProfiles; Register screen 2.24",
    "UC2 spec 2.2.2; sequence 2.5/2.6; HubService; Hubs table; screens 2.27/2.28",
    "HubLoadService.GetLoad; sequence 2.5; R2 screen 2.31",
    "HubLoadService.FindAlternatives; UC1 sequence 2.2 (alt ≥ 90%); pricing pipeline 2.16 gate 4",
    "PricingService.Validate (BR12); OrderLine; menu screen 2.19",
    "PricingService.Validate (BR1); pricing pipeline 2.16",
    "PricingService.Validate (BR2); home screen 2.18 (out of coverage)",
    "PricingService.DeliveryFee (BR3); checkout 2.20",
    "PricingService.RushSurcharge (BR4); checkout 2.21",
    "PricingService.RainSurcharge; PriceSnapshot.HeavyRainOn; checkout 2.21",
    "PricingService.DeliveryFee waiver (BR6); checkout 2.21",
    "PricingService.QuietDiscount (BR7); HubLoadService; checkout 2.20",
    "PricingService.VoucherDiscount; Voucher entity; checkout 2.21",
    "PricingService.Quote / RoundOnce (BR10, BR11); pricing pipeline 2.16",
    "IPaymentStrategy + 5 strategies + PaymentStrategyResolver (class diagram 2.11)",
    "CashOnDeliveryStrategy; state OutForDelivery → Delivered guard (2.7); shipper screen 2.29",
    "OrderStateMachine transition table; state diagram 2.7",
    "OrderService.EditItems; PriceSnapshot (BR17); UC1 spec A3",
    "OrderService.Cancel; OrderStateMachine; tracking screen 2.23",
    "IPaymentStrategy.Refund; Payment.RefundedAt; state entry actions 2.7",
    "IsActive / IsDeleted flags + query filters (DB notes 2.4.3); HubService.Deactivate",
    "ReportService.Revenue; R1 screen 2.30",
    "ReportService.HubUtilization; R2 screen 2.31",
    "Tracking view; OrderStatusHistory; screen 2.23",
    "Brand, HubBrands (ERD 2.12)",
    "MenuItem (ERD 2.12); menu screen 2.19",
    "Voucher (ERD 2.13)",
    "Users + StaffProfiles; Identity roles",
    "SystemSetting.HeavyRainOn; dashboard switch 2.26",
    "Order.ShipperId; state guard Ready → Out for Delivery (A-01)",
    "Order.DeliveryAddress, DistanceKm (ERD 2.13)",
    "[Authorize(Roles)] + ownership checks in services (architecture 2.14)",
    "PricingService in-memory pipeline (2.16)",
    "Strategy pattern 2.11 + single PricingService (2.10)",
    "Bootstrap grid, EN/VI resources; UI screens 2.18–2.33",
    "ASP.NET Core Identity PBKDF2; [Authorize(Roles)] (2.14)",
    "One transaction per operation + RowVersion (sequence 2.3, ERD 2.13)",
    "OrderStatusHistory append-only (2.7, ERD 2.13)",
    "PayPalSandboxStrategy; sequence 2.4",
    "DashboardService; dashboard screen 2.26",
    "Playwright E2E test project (quality gates, architecture 2.14)",
]
rtm = wb["RTM"]
for i, text in enumerate(DESIGN):
    row = 5 + i
    rtm[f"D{row}"] = text
    if row >= 46:
        for col in "ABCEFGHI":
            ref, cell = rtm[f"{col}45"], rtm[f"{col}{row}"]
            if cell.value is None and ref.value is not None and col in "EG":
                cell.value = ref.value
            cell.font, cell.alignment, cell.border, cell.fill = copy.copy(ref.font), copy.copy(ref.alignment), copy.copy(ref.border), copy.copy(ref.fill)
    if rtm[f"E{row}"].value in (None, ""):
        rtm[f"E{row}"] = "Pending Part 3"
    rtm[f"I{row}"] = "Part 2: design element linked; code and tests follow in Part 3."

# ---- Tier Checklist (student column = design status, notes = evidence)
tc = wb["Tier Checklist"]
notes = {
    6: ("Designed", "ASP.NET Core MVC + EF Core Code First + SQL Server + Bootstrap 5 (report 1.1, 2.5)"),
    7: ("Designed", "Architecture 2.14: Presentation / Business / Data; controllers hold no rules"),
    8: ("Designed", "Bootstrap 5 prototype at 390 and 1440 px (2.6)"),
    9: ("Designed", "IPaymentStrategy + 5 classes + resolver by customer type (2.11)"),
    10: ("Designed", "PricingService only (2.10, 2.16)"),
    11: ("Designed", "OrderStateMachine transition table (2.7)"),
    12: ("Designed", "R1 and R2 screens (2.30, 2.31) and ReportService"),
    13: ("Planned", "Repository github.com/bminhnemhoi/saigonbite-g7 created; tagged release in Part 3"),
    15: ("Designed", "PayPal Developer sandbox, Orders v2 (FR36, sequence 2.4); owner 524H0055"),
    16: ("Designed", "Interactive dashboard (FR37, screen 2.26); owner 524H0169"),
    17: ("Planned", "Playwright suite (NFR7); owners both"),
}
for row, (status, note) in notes.items():
    tc[f"C{row}"] = status
    tc[f"E{row}"] = note

# ---- Feedback Log
fb = wb["Feedback Log"]
rows = [
    ("Presentation 1", "Instructor approved moving from Tier 3 to Tier 4.", "Tier set to 4 on the cover and in 1.1; FR36, FR37, NFR7 added; Tier 4 parts designed in Part 2; this workbook updated.", "Cover, 1.1, 1.3, 1.4, 2.3–2.6", "Yes", ""),
    ("Presentation 1", "Assumptions A-01, A-02 and A-06 raised for confirmation.", "Kept and used consistently in the design; the written answer will be recorded in 1.5.", "1.5, 2.2, 2.3", "Open", ""),
]
for i, vals in enumerate(rows):
    row = 5 + i
    for j, v in enumerate(vals):
        col = "ABCDEF"[j]
        cell = fb[f"{col}{row}"]
        cell.value = v
        ref = fb[f"{col}5"]
        cell.font, cell.alignment, cell.border, cell.fill = copy.copy(ref.font), copy.copy(ref.alignment), copy.copy(ref.border), copy.copy(ref.fill)

wb.save(dst)
print("saved", dst)
